UPDATE lessons SET title='Year 4, Week 36, Lesson 2: Fitness testing and goals', data=json_patch(data,'{"child_mission":"Fitness testing in class uses friendly baselines (e.g. how many star jumps in 30s) to set improvement goals — not public humiliation rankings.","coming_soon":null,"duration_minutes":55,"evidence_instructions":"Save the independent response, specific revisions and both short-answer explanations; record oral evidence for speaking tasks.","explicit_teaching":null,"extension":"Apply the same idea to a new game or situation, then compare two choices for safety and inclusion.","follow_up_challenges":null,"guided_practice":"PRACTISE BEFORE READING THE FEEDBACK\nWhy avoid reading everyone’s scores aloud to mock?\n\nFEEDBACK\nIt shames and reduces motivation.\n\nWATCH FOR\nComparing only to the class champion can discourage.","hoard_words":null,"independent_task":"INDEPENDENT EVIDENCE\nComplete two friendly tests. Set one improvement goal. Retest plan dated.\n\nWrite a short reflection naming one choice you changed and why. Any movement is optional, adult-supervised and can be done in a gentler way or described instead.","interactive_activities":null,"learning_area":"PDHPE","learning_intention":"Fitness testing in class uses friendly baselines (e.g. how many star jumps in 30s) to set improvement goals — not public humiliation rankings.","lesson_number":2,"lesson_role":"Practise and apply","materials":["Paper or typed answer space","Pencil","Clear, safe movement space with an adult nearby for any physical activity","Optional: soft ball, cushion or water bottle"],"offline_alternative":"Use paper and pencil to complete the original task, then retain a photograph or short parent observation as evidence.","outcome_codes":["PH2-IHW-01"],"parent_notes":"Parent: Marking guidance for the independent task: Complete two friendly tests. Set one improvement goal. Retest plan dated. Accept equivalent original responses that show the same skill.\n\nParent: Written model 